import { WorkerClient } from "./runtime/worker-client";

const code = `def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
two_sum([2,15,11,7], 9)`

async function executeTrace() {
    const workerClient = new WorkerClient('/src/worker/worker.ts')

    console.log("Running Python computation in background thread...");

    const workerResponse = await workerClient.run(code)
    
    console.log(
        {
            trace: workerResponse.trace, 
            duration: workerResponse.duration?.toFixed(2)
        }
    );

    console.log("Pyodide execution success! Trace:");

    workerClient.terminate();
}

executeTrace();